cd /workspace; echo "---base vs workspace .claude identical?"; for f in $(cd pr/base && find .claude tools tests .loa.config.yaml .loa.config.yaml.example .github -type f 2>/dev/null); do [ -f "$f" ] || { echo "MISSING in ws: $f"; continue; }; cmp -s "pr/base/$f" "$f" || echo "DIFF: $f"; done | head -20; echo "---verdict-derive on trailerless"; printf 'All good\n\nSprint 1 reviewed.\n' > /tmp/nt.md; .claude/scripts/verdict-derive.sh --file /tmp/nt.md --gate review --json; echo "exit=$?"; echo "---floor corpus rows changed?"; python3 -I - <<'EOF'
import json
def load(p):
    d={}
    for l in open(p):
        l=l.strip()
        if not l: continue
        try: o=json.loads(l)
        except Exception as e: print("BAD",p,l[:80]); continue
        d[o.get('id')]=o
    return d
b=load('pr/base/tests/fixtures/fence-corpus/corpus.jsonl'); h=load('pr/head/tests/fixtures/fence-corpus/corpus.jsonl')
print("base",len(b),"head",len(h))
for k in b:
    if k not in h: print("REMOVED",k,b[k].get('rule'))
    elif b[k]!=h[k]:
        r=b[k].get('rule','')
        flag = 'FLOOR' if (r=='FR-1.2b' or str(r).startswith('FR-SZ')) else ''
        print("CHANGED",k,r,flag)
        print("  base:",json.dumps(b[k])[:300]); print("  head:",json.dumps(h[k])[:300])
new=[k for k in h if k not in b]
print("ADDED",len(new),new[:80])
EOF
